SELECT (SELECT COUNT(*) FROM products WHERE deleted=0) AS prod_alive, (SELECT COUNT(*) FROM products) AS prod_all, (SELECT COUNT(*) FROM product_images) AS imgs, (SELECT COUNT(*) FROM product_images WHERE url NOT LIKE '%placehold.co%') AS real_imgs, (SELECT COUNT(DISTINCT product_id) FROM product_images WHERE url NOT LIKE '%placehold.co%') AS prod_with_real, (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='geek_price') AS tbls;